import{_ as r,o as t,a as s,d as a}from"./chunks/framework.IehvnstE.js";const u=JSON.parse(`{"title":"Servers","description":"Minecraft servers in Stuzhik: creating and importing, a console with RCON, a server.properties editor, players, EULA, restart on crash and friends' servers. For Linux without a window there is a console version.","frontmatter":{"description":"Minecraft servers in Stuzhik: creating and importing, a console with RCON, a server.properties editor, players, EULA, restart on crash and friends' servers. For Linux without a window there is a console version.","head":[["meta",{"name":"keywords","content":"minecraft server, create minecraft server, server.properties editor, rcon minecraft, minecraft whitelist, modded server, stuzhik server"}]]},"headers":[],"relativePath":"en/guide/servers.md","filePath":"en/guide/servers.md"}`),n={name:"en/guide/servers.md"};function o(i,e,d,h,l,c){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="servers" tabindex="-1">Servers <a class="header-anchor" href="#servers" aria-label="Permalink to &quot;Servers&quot;">​</a></h1><p>Your own Minecraft server right from the launcher: create it, add mods, start it and run it from the console. It is a build like any other, only without graphics: with its own mods, world and settings. For a server on Linux without a window there is a <a href="/en/guide/cli.html">console version</a>: it shares its data with the app.</p><h2 id="creating" tabindex="-1">Creating <a class="header-anchor" href="#creating" aria-label="Permalink to &quot;Creating&quot;">​</a></h2><ul><li><strong>«Create» → server</strong>: the game version and a loader, as for a client</li><li><strong>Importing a server</strong>: Ctrl+K → «Import» → the «Server» tab, then «Server Folder» with a ready server. The launcher finds out the game version, loader, port and number of players by itself</li><li><strong>«Convert to Server»</strong> in a client build&#39;s menu: client mods (minimaps, shaders, interface) are turned off by themselves</li></ul><p><strong>Without accepting the Minecraft EULA the server doesn&#39;t start</strong>: the launcher asks for it before the first start.</p><h2 id="server-tabs" tabindex="-1">Server tabs <a class="header-anchor" href="#server-tabs" aria-label="Permalink to &quot;Server tabs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tab</th><th>What is there</th></tr></thead><tbody><tr><td>Console</td><td>the server&#39;s output and commands</td></tr><tr><td>Mods, Datapacks</td><td>the server&#39;s mods and datapacks</td></tr><tr><td>Modpack</td><td>updating the modpack, if the server was installed from one</td></tr><tr><td>Files, Profiles</td><td>the config editor</td></tr><tr><td>Server Settings</td><td>server.properties, players, EULA</td></tr><tr><td>Backups</td><td>backups of the server and its world</td></tr><tr><td>Analyze Logs</td><td>analysis of a server crash (<a href="/en/guide/log-analyzer.html">Log Analyzer</a>)</td></tr></tbody></table><p>On the «Mods» tab, «Client-only mods» finds the mods the server doesn&#39;t need and turns them off.</p><h2 id="console" tabindex="-1">Console <a class="header-anchor" href="#console" aria-label="Permalink to &quot;Console&quot;">​</a></h2><p>The server&#39;s output live, an «All» / «Errors» filter and command history with the ↑↓ keys. «Stop server (stop)» saves the world; «Force Kill» cuts the process off and may lose data.</p><p>If RCON is on, commands go through it, the console shows how many players are online, and «Say» works: a message to all players. <strong>RCON is off by default</strong>: turn it on and set a password in «Server Settings» → «Settings» → «RCON». The password lives in server.properties, so <strong>don&#39;t open the RCON port to the internet</strong>.</p><h2 id="server-settings" tabindex="-1">Server settings <a class="header-anchor" href="#server-settings" aria-label="Permalink to &quot;Server settings&quot;">​</a></h2><ul><li><strong>Settings</strong>: server.properties by group: network, world, gameplay, performance, security, RCON, Query. Values are saved as written (a long world seed doesn&#39;t turn into another number). Changes take effect after a restart</li><li><strong>Players</strong>: whitelist, operators and bans. On a server without licence checks it works with offline names too</li><li><strong>EULA</strong>: accept the Minecraft agreement</li></ul><p>In «Edit», a server has its port and «Restart on crash»: <strong>a crashed server comes back up by itself</strong>.</p><h2 id="friends-servers" tabindex="-1">Friends&#39; servers <a class="header-anchor" href="#friends-servers" aria-label="Permalink to &quot;Friends&#39; servers {#friends-servers}&quot;">​</a></h2><p>«Friends» shows the servers your friends have opened and the ones they are playing on now. For each you see how it is right now: latency, how many players are online, the version and the server message, as in the game&#39;s own server list. The launcher asks the server when you open its room and when you press «Ask again»; if it doesn&#39;t answer, it says so.</p><p>«Join» downloads the server&#39;s build (or fetches what is missing), fills in the address and starts the game. More about friends and passing builds: <a href="/en/guide/connect.html">Stuzhik Connect</a>.</p>',17)])])}const v=r(n,[["render",o]]);export{u as __pageData,v as default};
